local T=dofile('tests/kernel_adapter_binding_harness.lua')
local client=T.new();client.mount();assert(client.target.framework==nil and client.active()==0 and client.source.pulls==0,'83 construction inert')
assert(client.api.Install()and client.active()==9 and client.target.framework==client.aliases.framework)
client.emit('QBCore:Player:SetPlayerData',T.C.data());assert(client.target.framework.GetPlayer().fullName=='Ana Forge')
client.emit('QBCore:Client:SetDuty',false);assert(client.target.framework.GetPlayerJob().onduty==false)
local held=client.target.framework;client.api.Close();assert(client.api.Progress().complete and client.active()==0 and client.target.framework==nil and client.aliases.framework==nil)
assert(held.GetPlayerData()==nil);client.emit('QBCore:Player:SetPlayerData',{});assert(client.source.view.PlayerData.citizenid=='A80')
local server=T.new('server');server.mount();assert(server.api.Install()and server.active()==0)
assert(server.target.framework.GetIdentifier(1)=='C81')
local n=server.wire.server.active();local calls=0
server.target.framework.RegisterCallback('forge83:owned',function(source,...)calls=calls+1;return source,... end)
assert(server.wire.server.active()==n+1 and server.wire.server.find('forge83:owned'))
T.H.same(table.pack(server.wire.client.api.native.await('forge83:owned',5000,false,nil,83)),table.pack(2,false,nil,83),'whole installed callback wire/tuple')
assert(not pcall(server.target.framework.RegisterCallback,'forge83:owned',function()end),'PR lease collision refused')
local event=server.wire.server.find('forge83:owned');assert(server.api.Close()and server.api.Progress().complete)
assert(event.removed and server.wire.server.active()==n and calls==1,'only callback lease removed,transport listeners retained')
local conflict=T.new();conflict.target.framework={qbx=true};conflict.mount()
assert(not pcall(conflict.api.Install)and conflict.target.framework.qbx and conflict.active()==0);conflict.api.Close()
local foreign=T.new();foreign.mount();foreign.api.Install();foreign.aliases.framework={foreign=true}
assert(foreign.target.framework.GetPlayerData()==nil);foreign.api.Close();assert(foreign.aliases.framework.foreign)
print('PASS lot83 binding:actual80/81,9 client events,shared framework publication,empty-slot collision,53 server methods and installed PR native owned callback lease/collision/removal,foreign preservation;virtual only')
